script:
card({ name: "Rock paper scissors", icon: 'fist', permissions: ['sound'] });
const words = {
  rock: "Rock",
  paper: "Paper",
  scissors: "Scissors",
  pick: "Pick one. It stays hidden until both have picked.",
  picked: "You picked {p0}. Waiting for the other player.",
  theyPicked: "{p0} has picked",
  already: "You've already picked",
  full: "Two people are already playing",
  watching: "Two people are playing",
  youWon: "You won!",
  won: "{p0} won",
  draw: "It's a draw",
  someone: "the other player",
  again: "New game",
};

// Two players pick in secret. Picks show once both have picked.
const moves = ['rock', 'paper', 'scissors'];
const icons = { rock: '✊', paper: '✋', scissors: '✌️' };
const beats = { rock: 'scissors', paper: 'rock', scissors: 'paper' };

function init() {
  return { players: [], names: {}, picks: {}, score: {}, last: null };
}

on.pick = (s, args, ctx) => {
  if (!moves.includes(args.move)) return;
  if (!s.players.includes(ctx.author)) {
    if (s.players.length >= 2) throw words.full;
    s.players.push(ctx.author);
    s.score[ctx.author] = 0;
  }
  if (s.picks[ctx.author]) throw words.already;
  s.names[ctx.author] = ctx.authorName;
  s.picks[ctx.author] = args.move;
  if (s.players.length < 2) return;
  const [a, b] = s.players;
  if (!s.picks[a] || !s.picks[b]) return;
  const winner = s.picks[a] === s.picks[b] ? null : beats[s.picks[a]] === s.picks[b] ? a : b;
  if (winner) s.score[winner] += 1;
  s.last = { a: s.picks[a], b: s.picks[b], winner };
  ctx.sound(winner ? 'win' : 'pop');
  s.picks = {};
};

on.reset = (s) => init();

function view(s, me) {
  const name = id => s.names[id] || words.someone;
  const parts = [];
  const [a, b] = s.players;
  if (s.last) {
    parts.push(text(icons[s.last.a] + '  ' + icons[s.last.b], { size: 'huge', align: 'center' }));
    parts.push(text(name(a) + ' · ' + name(b), { size: 'small', tone: 'muted', align: 'center' }));
    const result = !s.last.winner ? words.draw : s.last.winner === me.id ? words.youWon : words.won.replace('{p0}', name(s.last.winner));
    parts.push(text(result, { bold: true, align: 'center', tone: s.last.winner === me.id ? 'success' : undefined }));
  }
  if (b) parts.push(row([badge(name(a) + ' ' + s.score[a], { tone: 'accent' }), badge(name(b) + ' ' + s.score[b], { tone: 'warning' })], { align: 'center' }));
  for (const p of s.players) {
    if (p !== me.id && s.picks[p]) parts.push(text(words.theyPicked.replace('{p0}', name(p)), { tone: 'muted', align: 'center' }));
  }
  const mine = s.picks[me.id];
  const playing = s.players.includes(me.id) || s.players.length < 2;
  if (!playing) parts.push(text(words.watching, { tone: 'muted', align: 'center' }));
  else if (mine) parts.push(text(words.picked.replace('{p0}', icons[mine]), { align: 'center' }));
  else parts.push(text(words.pick, { align: 'center' }));
  if (playing && !mine) {
    parts.push(row(moves.map(m => button(icons[m] + ' ' + words[m], 'pick', { move: m }, { tone: 'accent' })), { align: 'center' }));
  }
  if (s.last) parts.push(button(words.again, 'reset', null, { tone: 'muted', align: 'center' }));
  return column(parts);
}
